import { shellui } from '@shellui/sdk';
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { Link, useLocation, useNavigate } from 'react-router';
import urls from '../../../constants/urls';
import { cn } from '../../../lib/utils';
import { useIsMobile } from '../../../hooks/use-mobile';
import { useAuth } from '../hooks/useAuth';
import { UserIcon } from '../../settings/components/UserIcon';
import { useConfig } from '../../config/useConfig';
import { getAdminPath } from '../../admin/config';
import { isAdminPath } from '../../admin/utils';
import { flattenNavigationItems, getNavPathPrefix } from '../../layouts/utils';
import { LogoutIcon, SidebarCaretIcon } from './LoginButtonIcons';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '../../../components/ui/dropdown-menu';

type LoginButtonVariant = 'sidebar' | 'appbar' | 'windows';

const AdministrationIcon = ({ className }: { className?: string }) => (
  <svg
    xmlns="http://www.w3.org/2000/svg"
    width="24"
    height="24"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="2"
    strokeLinecap="round"
    strokeLinejoin="round"
    className={className}
    aria-hidden
  >
    <path d="M12 3l8 4v5c0 5-3.5 8.6-8 9-4.5-.4-8-4-8-9V7l8-4z" />
    <path d="M9.5 12.5 11 14l3.5-3.5" />
  </svg>
);

const SettingsMenuIcon = ({ className }: { className?: string }) => (
  <svg
    xmlns="http://www.w3.org/2000/svg"
    width="24"
    height="24"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="2"
    strokeLinecap="round"
    strokeLinejoin="round"
    className={className}
    aria-hidden
  >
    <circle
      cx="12"
      cy="12"
      r="3"
    />
    <path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 0 1 0 2.83 2 2 0 0 1-2.83 0l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-2 2 2 2 0 0 1-2-2v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 0 1-2.83 0 2 2 0 0 1 0-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1-2-2 2 2 0 0 1 2-2h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 0 1 0-2.83 2 2 0 0 1 2.83 0l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 2-2 2 2 0 0 1 2 2v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 0 1 2.83 0 2 2 0 0 1 0 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 2 2 2 2 0 0 1-2 2h-.09a1.65 1.65 0 0 0-1.51 1z" />
  </svg>
);

const variantConfig: Record<
  LoginButtonVariant,
  {
    button: { authenticated: string; loggedOut: string };
    avatar: string;
    menu: { width: string; side: 'top' | 'right' | 'bottom'; align: 'start' | 'end' };
    showDisplayName: boolean;
    showCaret: boolean;
  }
> = {
  sidebar: {
    button: {
      authenticated:
        'w-full h-8 rounded-md px-2 text-sm text-left text-sidebar-foreground hover:bg-sidebar-accent/50 hover:text-sidebar-foreground group-data-[collapsible=icon]:size-8! group-data-[collapsible=icon]:justify-center group-data-[collapsible=icon]:p-2!',
      loggedOut:
        'w-full h-8 rounded-md px-2 text-sm text-left text-sidebar-foreground hover:bg-sidebar-accent/50 hover:text-sidebar-foreground group-data-[collapsible=icon]:size-8! group-data-[collapsible=icon]:justify-center group-data-[collapsible=icon]:p-2!',
    },
    avatar: 'size-4',
    menu: { width: 'w-[min(16rem,calc(100vw-1.5rem))]', side: 'right', align: 'start' },
    showDisplayName: true,
    showCaret: true,
  },
  appbar: {
    button: {
      authenticated:
        'size-7 rounded-md p-0 justify-center text-sm text-muted-foreground hover:bg-sidebar-accent/50 hover:text-sidebar-foreground',
      loggedOut:
        'h-7 max-w-[220px] rounded-md px-2 text-xs text-muted-foreground hover:bg-sidebar-accent/50 hover:text-sidebar-foreground',
    },
    avatar: 'size-4',
    menu: { width: 'w-[min(16rem,calc(100vw-1.5rem))]', side: 'bottom', align: 'end' },
    showDisplayName: false,
    showCaret: false,
  },
  windows: {
    button: {
      authenticated:
        'h-8 w-8 rounded-md p-0 justify-center text-xs text-sidebar-foreground hover:bg-sidebar-accent/50 hover:text-sidebar-foreground',
      loggedOut:
        'h-8 max-w-[180px] rounded-md px-2 text-xs text-sidebar-foreground hover:bg-sidebar-accent/50 hover:text-sidebar-foreground',
    },
    avatar: 'h-4 w-4',
    menu: { width: 'w-[min(15rem,calc(100vw-1.5rem))]', side: 'top', align: 'end' },
    showDisplayName: false,
    showCaret: false,
  },
};

export const LoginButton = ({
  variant,
  hideWhenLoggedOut = false,
  logoutOnly = false,
}: {
  variant: LoginButtonVariant;
  hideWhenLoggedOut?: boolean;
  logoutOnly?: boolean;
}) => {
  const currentVariantConfig = variantConfig[variant];
  const isMobile = useIsMobile();
  const { t } = useTranslation('common');
  const { config } = useConfig();
  const { isAuthenticated, user, logout } = useAuth();
  const location = useLocation();
  const navigate = useNavigate();
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const triggerRef = useRef<HTMLButtonElement | null>(null);
  const contentRef = useRef<HTMLDivElement | null>(null);

  const displayName = useMemo(() => {
    const name = user?.name?.trim();
    const email = user?.email?.trim();
    return name || email || t('authMenu.userFallback');
  }, [t, user?.email, user?.name]);

  const fallbackInitial = displayName.charAt(0).toUpperCase();
  const { showDisplayName, showCaret } = currentVariantConfig;
  const menuSide = variant === 'sidebar' && isMobile ? 'top' : currentVariantConfig.menu.side;
  const menuAlign = variant === 'sidebar' && isMobile ? 'start' : currentVariantConfig.menu.align;
  const menuCollisionPadding = isMobile ? 12 : 8;

  const baseButtonClasses = cn(
    'inline-flex items-center gap-2 min-w-0 shrink-0 transition-colors cursor-pointer',
    'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2',
    'disabled:pointer-events-none disabled:opacity-50 disabled:cursor-not-allowed',
    isAuthenticated
      ? currentVariantConfig.button.authenticated
      : currentVariantConfig.button.loggedOut,
  );
  const isOnRequiredAuthRoute = useMemo(() => {
    const nav = config.navigation;
    if (!nav || nav.length === 0) return false;
    const requiredItems = flattenNavigationItems(nav).filter((item) => item.requiresAuth);
    if (requiredItems.length === 0) return false;
    return requiredItems.some((item) => {
      const pathPrefix = getNavPathPrefix(item);
      return (
        location.pathname === pathPrefix ||
        location.pathname.startsWith(`${pathPrefix === '/' ? '' : pathPrefix}/`)
      );
    });
  }, [config.navigation, location.pathname]);

  const openProfileSettingsModal = useCallback(() => {
    setIsMenuOpen(false);
    shellui.openModal(`${urls.settings}/user`);
  }, []);

  const canAccessAdmin = useMemo(
    () => Boolean(user?.isStaff || user?.isCompanyOwner),
    [user?.isCompanyOwner, user?.isStaff],
  );
  const adminPath = getAdminPath(config);
  const isOnAdminRoute = useMemo(
    () => isAdminPath(location.pathname, config),
    [config, location.pathname],
  );

  const openAdminPanel = useCallback(() => {
    if (!canAccessAdmin) {
      return;
    }
    setIsMenuOpen(false);
    navigate(isOnAdminRoute ? '/' : adminPath);
  }, [adminPath, canAccessAdmin, isOnAdminRoute, navigate]);

  const handleLogout = useCallback(async () => {
    setIsMenuOpen(false);
    if (isOnRequiredAuthRoute) {
      navigate('/', { replace: true });
    }
    shellui.sendMessageToParent({
      type: 'SHELLUI_LOGOUT',
      payload: {},
    });
    await logout();
  }, [isOnRequiredAuthRoute, logout, navigate]);

  useEffect(() => {
    if (!isMenuOpen) {
      return;
    }

    const handlePointerDown = (event: PointerEvent) => {
      const target = event.target as Node | null;
      if (!target) return;
      if (triggerRef.current?.contains(target)) return;
      if (contentRef.current?.contains(target)) return;
      setIsMenuOpen(false);
    };

    const handleWindowBlur = () => {
      setIsMenuOpen(false);
    };

    document.addEventListener('pointerdown', handlePointerDown, true);
    window.addEventListener('blur', handleWindowBlur);

    return () => {
      document.removeEventListener('pointerdown', handlePointerDown, true);
      window.removeEventListener('blur', handleWindowBlur);
    };
  }, [isMenuOpen]);

  if (!config.backend) {
    return null;
  }

  if (!isAuthenticated && hideWhenLoggedOut) {
    return null;
  }

  if (!isAuthenticated) {
    return (
      <Link
        to={urls.login}
        className={baseButtonClasses}
        aria-label={t('authMenu.goToLoginAriaLabel')}
        title={t('authMenu.login')}
      >
        <UserIcon />
        <span className="truncate group-data-[collapsible=icon]:hidden">{t('authMenu.login')}</span>
      </Link>
    );
  }

  if (!user) {
    return null;
  }

  return (
    <DropdownMenu
      open={isMenuOpen}
      onOpenChange={setIsMenuOpen}
      modal={false}
    >
      <DropdownMenuTrigger asChild>
        <button
          ref={triggerRef}
          type="button"
          className={baseButtonClasses}
          title={displayName}
          aria-label={t('authMenu.openAccountMenuAriaLabel', { name: displayName })}
        >
          {user.profilePicture ? (
            <img
              src={user.profilePicture}
              alt={displayName}
              className={cn(
                'shrink-0 overflow-hidden rounded-full border border-sidebar-border object-cover aspect-square',
                currentVariantConfig.avatar,
              )}
              referrerPolicy="no-referrer"
            />
          ) : (
            <span
              className={cn(
                'flex shrink-0 aspect-square items-center justify-center overflow-hidden rounded-full border border-sidebar-border bg-muted text-[10px] font-semibold leading-none',
                currentVariantConfig.avatar,
              )}
              aria-hidden
            >
              {fallbackInitial}
            </span>
          )}
          {showDisplayName && (
            <span className="truncate group-data-[collapsible=icon]:hidden">{displayName}</span>
          )}
          {showCaret && (
            <span
              aria-hidden
              className={cn(
                'ml-auto shrink-0 text-[10px] group-data-[collapsible=icon]:hidden',
                isMenuOpen ? 'text-foreground' : 'text-muted-foreground',
              )}
            >
              <SidebarCaretIcon
                isOpen={isMenuOpen}
                className="h-3 w-3"
              />
            </span>
          )}
        </button>
      </DropdownMenuTrigger>
      <DropdownMenuContent
        ref={contentRef}
        forceMount
        data-auth-menu-content
        side={menuSide}
        align={menuAlign}
        collisionPadding={menuCollisionPadding}
        className={cn('p-1.5 max-w-[calc(100vw-1.5rem)]', currentVariantConfig.menu.width)}
        onPointerDownOutside={() => setIsMenuOpen(false)}
        onFocusOutside={() => setIsMenuOpen(false)}
        onEscapeKeyDown={() => setIsMenuOpen(false)}
      >
        <DropdownMenuLabel className="space-y-0.5">
          <p className="truncate text-sm font-semibold text-popover-foreground">{displayName}</p>
          <p className="truncate text-xs font-normal text-muted-foreground">
            {user.email || t('authMenu.noEmail')}
          </p>
        </DropdownMenuLabel>
        <DropdownMenuSeparator />
        {!logoutOnly && !isOnAdminRoute && (
          <DropdownMenuItem onSelect={openProfileSettingsModal}>
            <UserIcon />
            <span>{t('authMenu.profile')}</span>
          </DropdownMenuItem>
        )}
        {logoutOnly && (
          <DropdownMenuItem onSelect={openProfileSettingsModal}>
            <SettingsMenuIcon className="h-4 w-4" />
            <span>{t('authMenu.settings')}</span>
          </DropdownMenuItem>
        )}
        {!logoutOnly && canAccessAdmin && (
          <DropdownMenuItem onSelect={openAdminPanel}>
            <AdministrationIcon className="h-4 w-4" />
            <span>
              {isOnAdminRoute
                ? t('authMenu.backToHome', { defaultValue: 'Back to home' })
                : t('authMenu.administration')}
            </span>
          </DropdownMenuItem>
        )}
        <DropdownMenuItem
          onSelect={() => void handleLogout()}
          className="text-destructive focus:text-destructive"
        >
          <LogoutIcon className="h-4 w-4" />
          <span>{t('authMenu.logout')}</span>
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
};
